# training_history.py
"""Archive an audited training CSV in private SQLite storage without generating calendar events.

Command-line use: python training_history.py path/to/export.csv
"""
#
# AI CITATION
# Generated by: OpenAI Codex (GPT-6), 2026-11-15
# Last AI change: 2026-11-15, Task 3 private training archive
# Based on: approved Tasks 1–3; WeekWise SPEC.md v1.0 sections 6, 7, 18, 19
# Prompt summary: Preserve the original training values and make repeated imports idempotent.
# Scope: entire file, except blocks marked "# Written by the team"
