# Changes by the team: none

import argparse
from datetime import date, datetime
import hashlib
from io import BytesIO
from pathlib import Path
import sqlite3

import pandas as pd

import config
import database


INSERT_HISTORY_SQL = '''INSERT INTO training_history
    (import_id,source_row,sport,variant,weekday_text,start_time,date_original,training_date,
     participants_signed_up,participants_teacher,max_participants)
    VALUES (?,?,?,?,?,?,?,?,?,?,?)'''

READ_HISTORY_SQL = '''SELECT source_row,sport,variant,weekday_text,start_time,date_original,
    training_date,participants_signed_up,participants_teacher,max_participants
    FROM training_history WHERE import_id=? ORDER BY source_row'''


def parse_training_date(text):
    """Read the exported German date text without requiring a German system locale.

    :param text: for example Mittwoch, 4. November 2026
    :return: validated datetime.date; error messages do not repeat private input
    """
    try:
        weekday, rest = text.split(',')
        day, month, year = rest.strip().split()
        if (not day.endswith('.') or month not in config.TRAINING_MONTHS
                or len(year) != 4 or not year.isascii() or not year.isdecimal()):
            raise ValueError('Invalid date spelling.')
        value = date(int(year), config.TRAINING_MONTHS[month], int(day[:-1]))
        if weekday != config.TRAINING_WEEKDAYS_DE[value.weekday()]:
            raise ValueError('Weekday mismatch.')
        return value
    except (ValueError, TypeError, KeyError, AttributeError):
        raise ValueError('Invalid German date in Termin.') from None


def _training_count(text, field):
    """Preserve blank counts as NULL, keeping actual zeros and nonnegative integers distinct."""
    if text == '':
        return None
    if not text.isascii() or not text.isdecimal():
        raise ValueError(f'Invalid integer in {field}.')
    significant = text.lstrip('0') or '0'
    if len(significant) > len(str(config.MAX_SQLITE_INTEGER)):
        raise ValueError(f'Integer outside SQLite range in {field}.')
    value = int(significant)
    if value > config.MAX_SQLITE_INTEGER:
        raise ValueError(f'Integer outside SQLite range in {field}.')
    return value


def _training_record(values, source_row):
    """Validate one original row, adding only an ISO date and its source-row reference."""
    try:
        sport, variant, weekday, start, original_date, signed_up, teacher, capacity = values
        parsed = parse_training_date(original_date)
        if weekday != config.TRAINING_WEEKDAYS_EN[parsed.weekday()]:
            raise ValueError('Tag does not match Termin.')
        try:
            clock = datetime.strptime(start, config.SOURCE_TIME_FORMAT)
            if clock.strftime(config.SOURCE_TIME_FORMAT) != start:
                raise ValueError('Noncanonical start time.')
        except ValueError:
            raise ValueError('Invalid start time in Zeit.') from None
        # Course: U03 s4 – unpacking and tuples keep a stable order for SQL parameters.
        return (source_row, sport if sport != '' else None, variant if variant != '' else None,
                weekday, start, original_date, parsed.isoformat(),
                _training_count(signed_up, 'Teilnehmer signed up'),
                _training_count(teacher, 'Teilnehmer teacher'),
                _training_count(capacity, 'Max participants'))
    except ValueError as error:
        raise ValueError(f'Row {source_row}: {error}') from None


def read_training_csv(path):
    """Read and validate a bounded export completely before allowing a database write.

    :param path: private CSV path, UTF-8 with optional BOM and semicolon-separated fields
    :return: filename, SHA-256 source fingerprint and validated record tuples
    """
    path = Path(path)
    with path.open('rb') as stream:
        payload = stream.read(config.MAX_TRAINING_CSV_BYTES + 1)
    if len(payload) > config.MAX_TRAINING_CSV_BYTES:
        raise ValueError('Training CSV exceeds the byte limit.')
    try:
        # Course: A08, Unit07 bonus – keep blanks and literal NA text until explicit validation.
        # Reading the header as data also exposes duplicate column names without auto-renaming.
        frame = pd.read_csv(BytesIO(payload), sep=config.TRAINING_CSV_SEPARATOR,
                            encoding=config.TRAINING_CSV_ENCODING, header=None, engine='python',
                            dtype=str, keep_default_na=False, na_filter=False,
                            skip_blank_lines=False, nrows=config.MAX_TRAINING_HISTORY_ROWS + 2)
    except (pd.errors.ParserError, pd.errors.EmptyDataError, UnicodeError, ValueError):
        raise ValueError('Training CSV is not a valid UTF-8 semicolon export.') from None
    if frame.shape[1] != len(config.TRAINING_CSV_HEADERS):
        raise ValueError('Training CSV must contain exactly eight columns.')
    if tuple(frame.iloc[0]) != config.TRAINING_CSV_HEADERS:
        raise ValueError('Training CSV headers do not match the audited export.')
    if not 0 < len(frame) - 1 <= config.MAX_TRAINING_HISTORY_ROWS:
        raise ValueError('Training CSV row count is empty or exceeds the archive limit.')
    records = []
    for source_row, values in enumerate(frame.iloc[1:].itertuples(index=False, name=None), 2):
        if any(not isinstance(value, str) for value in values):
            raise ValueError(f'Row {source_row}: incorrect number of CSV fields.')
        records.append(_training_record(values, source_row))
    # Technical provenance helper for approved Task 2, not a claimed Week07 database method.
    # Hash the same bounded bytes that pandas actually parsed, not a second read of the file.
    return {'file_name': path.name, 'source_fingerprint': hashlib.sha256(payload).hexdigest(),
            'records': records}


def _import_report(import_id, records, already_imported):
    """Summarize counts without printing personal source text or participant-level details."""
    values = [row[1:] for row in records]
    dates = [row[6] for row in records]
    return {'import_id': import_id, 'n_rows': len(records),
            'n_imported': 0 if already_imported else len(records),
            'already_imported': already_imported, 'first_date': min(dates), 'last_date': max(dates),
            'n_duplicate_rows': len(values) - len(set(values)),
            'n_unnamed_rows': sum(row[1] is None and row[2] is None for row in records)}


def import_training_csv(connection, path, now=None):
    """Append one validated archive atomically or verify an unchanged previous import.

    :param connection: initialized SQLite connection, with no active caller-owned transaction
    :param path: CSV path; its original bytes are never overwritten
    :param now: optional naive Zurich clock for reproducible import metadata
    :return: import ID, counts, dates and an already_imported flag
    """
    if connection.in_transaction:
        raise ValueError('Finish the current transaction before importing training history.')
    prepared = read_training_csv(path)
    records = prepared['records']
    stamp = database.to_db_text(config.local_now(now))
    # Course: A07 – the file metadata and all history rows commit or roll back together.
    with connection:
        existing = connection.execute('''SELECT id FROM training_imports
            WHERE source_fingerprint=?''', (prepared['source_fingerprint'],)).fetchone()
        if existing is not None:
            import_id = existing['id']
            stored = connection.execute(READ_HISTORY_SQL, (import_id,)).fetchall()
            if [tuple(row) for row in stored] != records:
                raise ValueError('The stored archive differs from its source; no repair attempted.')
            return _import_report(import_id, records, True)
        cursor = connection.execute('''INSERT INTO training_imports
            (file_name,source_fingerprint,imported_at) VALUES (?,?,?)''',
            (prepared['file_name'], prepared['source_fingerprint'], stamp))
        import_id = cursor.lastrowid
        parameters = [(import_id,) + row for row in records]
        connection.executemany(INSERT_HISTORY_SQL, parameters)
    return _import_report(import_id, records, False)


def main():
    """Run the explicit private archive command and print only aggregate verification results."""
    arguments = argparse.ArgumentParser(description=__doc__)
    arguments.add_argument('csv_file', type=Path)
    arguments.add_argument('--database', type=Path, default=config.TRAINING_HISTORY_DB)
    options = arguments.parse_args()
    connection = None
    try:
        # Validate before opening/creating even an empty archive file on malformed input.
        read_training_csv(options.csv_file)
        connection = database.get_connection(options.database)
        database.init_db(connection)
        report = import_training_csv(connection, options.csv_file)
    except (OSError, sqlite3.Error):
        arguments.exit(1, 'Could not read the source or write the private training archive.\n')
    except ValueError as error:
        arguments.exit(1, str(error) + '\n')
    finally:
        if connection is not None:
            connection.close()
    print(f'Import {report["import_id"]}: {report["n_rows"]} source rows; '
          f'{report["n_imported"]} newly stored.')
    print(f'Historical dates: {report["first_date"]} to {report["last_date"]}.')
    print(f'Preserved duplicate rows: {report["n_duplicate_rows"]}; '
          f'rows without both sport labels: {report["n_unnamed_rows"]}.')
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
